item.text:
Скин — цифровой товар, поэтому **внутри Telegram Mini App его нужно продавать за Telegram Stars (`XTR`)**. Принимать TON за такую покупку правила Telegram не разрешают. [Официальное правило](https://core.telegram.org/bots/payments-stars#can-i-accept-payment-in-cryptocurrency-instead-of-telegram-stars).

Ниже пример со Stars. `200 XTR` — условная цена, **не эквивалент 2 TON**.

Фронтенд передаёт `initData` серверу, получает ссылку на счёт и открывает её через [`openInvoice`](https://core.telegram.org/bots/webapps#initializing-mini-apps):

```html
<script src="https://telegram.org/js/telegram-web-app.js"></script>
<button id="buy">Купить премиум-скин</button>
<p id="status"></p>

<script>
const tg = Telegram.WebApp;
tg.ready();

document.querySelector('#buy').onclick = async () => {
  const status = document.querySelector('#status');

  try {
    const response = await fetch('/api/skin/invoice', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ initData: tg.initData })
    });
    if (!response.ok) throw new Error('Не удалось создать счёт');

    const { url } = await response.json();

    tg.openInvoice(url, paymentStatus => {
      status.textContent = paymentStatus === 'paid'
        ? 'Обновляем инвентарь с сервера…'
        : `Статус счёта: ${paymentStatus}`;

      // Здесь запросите актуальный инвентарь с вашего backend.
      // Сам callback не выдаёт скин.
    });
  } catch (error) {
    status.textContent = error.message;
  }
};
</script>
```

Бэкенд: Node.js + Express. **`db.*` ниже — псевдокод операций вашей постоянной БД**, их обязательный контракт указан после примера.

```js
import express from 'express';
import {
  createHmac, timingSafeEqual
} from 'node:crypto';

const app = express();
app.use(express.json({ limit: '16kb' }));

const TOKEN = process.env.BOT_TOKEN;
const WEBHOOK_SECRET = process.env.TELEGRAM_WEBHOOK_SECRET;
if (!TOKEN || !WEBHOOK_SECRET) throw new Error('Missing bot secrets');

const SKU = 'premium-skin';
const PRICE_XTR = 200; // Выберите свою целую цену в Stars.

async function telegram(method, body) {
  const response = await fetch(
    `https://api.telegram.org/bot${TOKEN}/${method}`,
    {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(body),
      signal: AbortSignal.timeout(5000)
    }
  );
  const data = await response.json();
  if (!response.ok || !data.ok) throw new Error(`Telegram: ${method}`);
  return data.result;
}

function verifyInitData(raw) {
  if (typeof raw !== 'string') throw new Error('Invalid initData');

  const params = new URLSearchParams(raw);
  const keys = [...params.keys()];
  if (new Set(keys).size !== keys.length) throw new Error('Duplicate fields');

  const hash = params.get('hash') ?? '';
  if (!/^[a-f0-9]{64}$/i.test(hash)) throw new Error('Invalid hash');
  params.delete('hash');

  // Для HMAC исключается только hash; signature, если есть, остаётся.
  params.sort();
  const checkString = [...params]
    .map(([key, value]) => `${key}=${value}`).join('\n');

  const secret = createHmac('sha256', 'WebAppData')
    .update(TOKEN).digest();
  const expected = createHmac('sha256', secret)
    .update(checkString).digest();

  if (!timingSafeEqual(expected, Buffer.from(hash, 'hex'))) {
    throw new Error('Invalid signature');
  }

  const authDate = Number(params.get('auth_date'));
  const age = Date.now() / 1000 - authDate;
  // Пример политики свежести: 1 час, допуск часов 30 секунд.
  if (!Number.isSafeInteger(authDate) || age < -30 || age > 3600) {
    throw new Error('Expired initData');
  }

  const user = JSON.parse(params.get('user') ?? 'null');
  if (!Number.isSafeInteger(user?.id) || user.id <= 0) {
    throw new Error('Invalid user');
  }
  return String(user.id);
}

function matches(order, userId, payment) {
  return order &&
    order.userId === String(userId) &&
    order.sku === SKU &&
    order.id === payment.invoice_payload &&
    order.currency === payment.currency &&
    order.amount === payment.total_amount;
}

app.post('/api/skin/invoice', async (req, res, next) => {
  let userId;
  try {
    userId = verifyInitData(req.body.initData);
  } catch {
    return res.sendStatus(401);
  }

  try {
    const order = await db.createOrReuseOrder({
      userId, sku: SKU, currency: 'XTR', amount: PRICE_XTR
    });

    const url = await telegram('createInvoiceLink', {
      title: 'Премиум-скин',
      description: 'Постоянный доступ к игровому скину',
      payload: order.id,
      provider_token: '',
      currency: order.currency,
      prices: [{ label: 'Премиум-скин', amount: order.amount }]
    });

    res.json({ url });
  } catch (error) {
    next(error);
  }
});

app.post('/telegram/webhook', async (req, res, next) => {
  if (req.get('X-Telegram-Bot-Api-Secret-Token') !== WEBHOOK_SECRET) {
    return res.sendStatus(403);
  }

  try {
    const query = req.body.pre_checkout_query;

    if (query) {
      const order = await db.getOrder(query.invoice_payload);
      const ok = Boolean(
        matches(order, query.from.id, query) &&
        await db.reserveCheckout(order.id, query.id)
      );

      await telegram('answerPreCheckoutQuery', {
        pre_checkout_query_id: query.id,
        ok,
        ...(ok ? {} : { error_message: 'Заказ недоступен для оплаты.' })
      });
    }

    const message = req.body.message;
    const payment = message?.successful_payment;

    if (payment) {
      const order = await db.getOrder(payment.invoice_payload);
      if (!matches(order, message.from?.id, payment)) {
        throw new Error('Payment does not match order');
      }

      await db.fulfillOnce({
        orderId: order.id,
        userId: order.userId,
        sku: order.sku,
        chargeId: payment.telegram_payment_charge_id
      });
    }

    // Подтверждаем доставку update после завершения операций БД.
    res.sendStatus(200);
  } catch (error) {
    next(error); // Ошибка => 500, Telegram повторит webhook.
  }
});

app.use((error, req, res, next) => {
  console.error(error.message);
  res.sendStatus(500);
});

app.listen(3000);
```

Для `db` нужны следующие гарантии:

- `createOrReuseOrder` сохраняет случайный уникальный ID заказа, пользователя, SKU, валюту и сумму, выбранные сервером; повторная покупка уже принадлежащего пользователю скина отклоняется.
- `reserveCheckout` атомарно резервирует заказ и скин для покупки. Повтор того же `query.id` допустим, конкурирующая оплата отклоняется. Зависшую резервацию снимают после сверки состояния платежа.
- `fulfillOnce` одной транзакцией записывает оплату и выдаёт скин. На `chargeId` нужен `UNIQUE`: повторная доставка того же платежа завершается успешно без повторной выдачи. Новый `chargeId` для уже оплаченного заказа требует учёта и возврата.
- Инвентарь и право использовать скин проверяются на сервере по сохранённой выдаче.

Настройте HTTPS webhook через `setWebhook` с `secret_token: WEBHOOK_SECRET` и `allowed_updates: ["pre_checkout_query", "message"]`. На pre-checkout необходимо ответить **за 10 секунд**; выдача разрешена после **`successful_payment`**. [Платёжный процесс](https://core.telegram.org/bots/payments-stars#step-by-step-process), [защита webhook](https://core.telegram.org/bots/api#setwebhook).

Проверка `initData` соответствует [официальной HMAC-схеме](https://core.telegram.org/bots/webapps#validating-data-received-via-the-mini-app). Добавьте `/paysupport` и обработку возвратов через [`refundStarPayment`](https://core.telegram.org/bots/api#refundstarpayment).
